<script setup lang="ts">
import {useProductivityStore,dateKey} from '~/stores/productivity'; import type {ScheduleBlock} from '~/types/domain'
const store=useProductivityStore(); const selected=ref(dateKey()); const open=ref(false); const title=ref(''); const kind=ref<ScheduleBlock['kind']>('work'); const start=ref('09:00'); const end=ref('10:00'); const taskId=ref('')
const blocks=computed(()=>store.schedule.filter(x=>x.date===selected.value)); const tasksForDay=computed(()=>store.tasks.filter(t=>t.scheduledDate===selected.value))
const add=()=>{if(!title.value.trim())return;store.addScheduleBlock({title:title.value,kind:kind.value,date:selected.value,start:start.value,end:end.value,taskId:taskId.value||undefined});open.value=false;title.value='';taskId.value=''}
const createFromTask=(t:any)=>{store.addScheduleBlock({title:t.title,kind:'task',date:selected.value,start:t.startTime||'09:00',end:t.endTime||'10:00',taskId:t.id});}
</script>
<template><div class="space-y-5"><div class="flex justify-between"><div><h1 class="text-2xl font-black">برنامه‌ریز</h1><p class="text-gray-500">برنامه را برای هر روز مستقل بچین و بعد از «امروز» اجرا کن.</p></div><div class="flex gap-2"><UInput v-model="selected" type="date"/><UButton icon="i-lucide-plus" @click="open=true">بلوک جدید</UButton></div></div><UCard><template #header><div class="flex justify-between"><b>برنامه {{new Date(selected+'T12:00').toLocaleDateString('fa-IR',{weekday:'long',day:'numeric',month:'long'})}}</b><UBadge variant="soft">{{blocks.length}} بلوک</UBadge></div></template><div v-if="blocks.length" class="space-y-3"><div v-for="b in blocks" :key="b.id" class="flex items-center gap-3 p-4 rounded-2xl border" :class="b.completed?'opacity-50':''"><span class="font-mono text-sm w-28">{{b.start}}–{{b.end}}</span><UIcon :name="b.completed?'i-lucide-circle-check':'i-lucide-clock-3'"/><div class="flex-1"><b :class="b.completed?'line-through':''">{{b.title}}</b><p class="text-xs text-gray-500 mt-1">{{b.kind}}</p></div><UButton v-if="b.taskId&&!b.completed" size="sm" @click="store.startTimer({label:b.title,durationSeconds:Math.max(60,(parseInt(b.end)-parseInt(b.start))*60),taskId:b.taskId,mode:'schedule'});navigateTo('/focus?taskId='+b.taskId)">اجرا</UButton><UButton v-if="!b.completed" icon="i-lucide-check" variant="ghost" color="success" @click="store.markScheduleDone(b.id)"/><UButton icon="i-lucide-trash-2" variant="ghost" color="error" @click="store.removeScheduleBlock(b.id)"/></div></div><p v-else class="text-center text-gray-500 py-10">برای این روز برنامه‌ای نیست.</p></UCard><UCard><template #header><b>کارهای این روز که هنوز در برنامه زمانی نیستند</b></template><div class="space-y-2"><div v-for="t in tasksForDay.filter(x=>!blocks.some(b=>b.taskId===x.id))" :key="t.id" class="flex items-center gap-3 p-3 rounded-xl bg-gray-50 dark:bg-gray-800/50"><span class="flex-1">{{t.title}}</span><UBadge>{{t.estimatedMinutes}}د</UBadge><UButton size="sm" variant="soft" @click="createFromTask(t)">وارد برنامه کن</UButton></div><p v-if="!tasksForDay.filter(x=>!blocks.some(b=>b.taskId===x.id)).length" class="text-sm text-gray-500">همه کارهای این روز برنامه‌ریزی شده‌اند.</p></div></UCard><UModal v-model:open="open"><template #content><UCard><template #header>بلوک زمانی جدید</template><div class="space-y-4"><UInput v-model="title" placeholder="عنوان"/><USelect v-model="kind" :items="['task','focus','study','work','break','personal']"/><USelect v-model="taskId" :items="[{label:'بدون اتصال',value:''},...tasksForDay.map(t=>({label:t.title,value:t.id}))]" value-key="value"/><div class="grid grid-cols-2 gap-3"><UInput v-model="start" type="time"/><UInput v-model="end" type="time"/></div><div class="flex justify-end gap-2"><UButton variant="ghost" @click="open=false">انصراف</UButton><UButton @click="add">ساخت</UButton></div></div></UCard></template></UModal></div></template>
